#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np(n);
        // suffix [n-y..n-1] -> [0..y-1]
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        // middle [x..n-y-1] -> [y..n-x-1]
        for(int i=x;i<n-y;i++) np[y+i-x]=p[i];
        // prefix [0..x-1] -> [n-x..n-1]
        for(int i=0;i<x;i++) np[n-x+i]=p[i];
        p=np;
    };

    for(int i=0;i<n-2;i++){
        int j=-1;
        for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;
        // Move element from position j to position i
        // Step 1: move to front (position 0) if not already
        if(j>0 && j<n-1){
            // op(j,1): elem at j in middle, goes to j-j+1=1. Then op(1,n-2): elem at 1 in middle goes to 0+n-2=n-2... no
            // op(1,n-1-j): elem at j is in suffix if j>=n-(n-1-j)=j+1, no j<j+1. middle [1..j], goes to (n-1-j)+(j-1)=n-2
            // Let's just use two ops to get it to position i directly
            // op(j,n-1-j): elem at j is middle, goes to j-j+(n-1-j)=n-1-j
            doOp(j,n-1-j);
            j=n-1-j;
        }
        if(j==i) continue;
        if(j==0 && i+1<=n-2 && i>=1){ doOp(1,n-1-i); j=find(p.begin(),p.end(),i+1)-p.begin(); if(j==i)continue;}
        if(j==n-1 && i<=n-3){ doOp(i+1,n-1-i-1); j=find(p.begin(),p.end(),i+1)-p.begin(); if(j==i)continue;}
        if(j!=i && j>0 && j<n-1){ doOp(j,n-1-j); j=n-1-j; }
        if(j==0 && i==0) continue;
        if(j!=i){ doOp(max(1,i),max(1,n-1-max(1,i))); /* fallback */ }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
